let language='en';
try{language=localStorage.getItem('portfolio-language')==='zh'?'zh':'en'}catch{}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=s=>s&&typeof s==='object'?(s[language]||s.en||''):s||'';
const groups=[{id:'creative',en:'Creative',zh:'创意',children:[{id:'creative-direction',en:'Creative Direction',zh:'创意指导'},{id:'production',en:'Production',zh:'制作'},{id:'social-media-curation',en:'Social Media Curation',zh:'社交媒体策划'}]},{id:'interactive',en:'Interactive',zh:'互动',children:[{id:'vibecoding',en:'Vibecoding',zh:'创意编程'},{id:'mixed-reality',en:'Mixed Reality',zh:'混合现实'}]},{id:'stills',en:'Stills',zh:'静态影像',children:[{id:'photography',en:'Photography',zh:'摄影'},{id:'poster',en:'Poster',zh:'海报'}]}];
const labels={en:{home:'Home',about:'About',role:'Role',images:'Images',films:'Films',back:'Back',next:'Next project',previous:'Previous project',visit:'Explore project ',empty:'Work to come.',emptyText:'A selection will be added here soon.',prevMedia:'Previous media',nextMedia:'Next media',image:'Image',film:'Film',skip:'Skip to content',menu:'Menu',intro:'Creative direction, image-making & interactive experiences.',selected:'Selected work.'},zh:{home:'首页',about:'关于',role:'角色',images:'照片',films:'视频',back:'返回',next:'下个项目',previous:'上个项目',visit:'在线体验 ',empty:'作品整理中。',emptyText:'更多作品将在这里呈现。',prevMedia:'上一组媒体',nextMedia:'下一组媒体',image:'图片',film:'视频',skip:'跳至内容',menu:'菜单',intro:'创意设计、影像与互动体验。',selected:'精选作品。'}};
const projects=PORTFOLIO.categories.flatMap(c=>c.projects.map(p=>({...p,section:p.section||({photography:'photography',poster:'poster',vr:'mixed-reality'}[c.id])})));
let page=document.body.dataset.page||'home';
const project=projects.find(p=>'project-'+p.id===page);
const selectedSection=project?.section||page;
const activeGroup=groups.find(g=>g.id===page||g.children.some(s=>s.id===selectedSection));
function href(id){return id==='home'?'index.html':id+'.html'}
function navigation(){return `<a class="nav-home ${page==='home'?'current':''}" href="index.html" ${page==='home'?'aria-current="page"':''}>${labels[language].home}</a><div class="nav-groups">${groups.map(g=>`<div class="nav-group"><a class="nav-primary ${activeGroup?.id===g.id?'active':''}" href="${href(g.id)}" aria-expanded="${activeGroup?.id===g.id}"><span class="nav-label">${g[language]}</span><span aria-hidden="true">${activeGroup?.id===g.id?'−':'+'}</span></a>${activeGroup?.id===g.id?`<div class="subnav">${g.children.map(s=>`<a href="${href(s.id)}" class="${selectedSection===s.id?'current':''}" ${page===s.id?'aria-current="page"':''}>${s[language]}</a>`).join('')}</div>`:''}</div>`).join('')}</div><a class="nav-about ${page==='about'?'current':''}" href="about.html" ${page==='about'?'aria-current="page"':''}>${labels[language].about}</a>`}
function home(){return `<section class="home-page"><div class="home-intro"><p class="eyebrow">${language==='zh'?'作品集':'Portfolio'} / Xin(Robynn)Shen</p><h1>${labels[language].selected}</h1><p class="tagline">${esc(PORTFOLIO.pages.tagline)}</p><div class="home-description"><p>${labels[language].intro}</p><p class="years">2024 — 2026</p></div></div><img class="home-image" src="${PORTFOLIO.pages.homeImage}" alt="${language==='zh'?'粉红色的抽象摄影':'An abstract photograph in shades of pink'}"></section>`}
function groupProjects(id){const group=groups.find(g=>g.id===id);return group?group.children.flatMap(section=>projects.filter(p=>p.section===section.id)):projects.filter(p=>p.section===id)}
function sectionLabel(id){return groups.flatMap(g=>g.children).find(s=>s.id===id)?.[language]||''}
function cover(p){return p.cover||p.gallery?.[0]||p.rows?.[0]?.[0]?.src||p.rows?.[0]?.[0]||p.demo?.poster||p.videos?.[0]?.poster}
function parentReturn(){return activeGroup&&page!==activeGroup.id?`<a class="mobile-parent-link" href="${href(activeGroup.id)}">${language==='zh'?'返回'+activeGroup.zh:'Back to '+activeGroup.en}</a>`:''}
function collectionHeader(title){return `<header class="page-heading">${parentReturn()}<p class="eyebrow">${language==='zh'?'静态影像':'Stills'} / ${title}</p><h1>${title}</h1></header>`}
function posterPage(){const title=sectionLabel('poster'),items=groupProjects('poster');return `<section class="index-page collection-page poster-page">${collectionHeader(title)}<div class="poster-grid">${items.map(p=>`<figure><img src="${esc(cover(p))}" alt="${esc(tr(p.title))}" title="${esc(tr(p.title))}" loading="lazy" decoding="async"></figure>`).join('')}</div></section>`}
function photographyCards(){return groupProjects('photography').map(p=>`<a class="project-card" href="${href('photography')}#${p.id}"><figure><img src="${esc(cover(p))}" alt="${esc(tr(p.title))}" loading="lazy" decoding="async"></figure><div class="card-meta"><h2>${esc(tr(p.title))}</h2><span aria-hidden="true"></span></div><p class="card-caption">${esc(tr(p.date)||sectionLabel(p.section))}</p></a>`).join('')}
function photoOrientation(src){const d=PORTFOLIO.dimensions[src]||[1,1],ratio=d[0]/d[1];return ratio>.115e1?'landscape':ratio<.87?'portrait':'square'}
function photoSlides(p){return (p.gallery||[]).map(src=>[src])}
function photographyPage(){const title=sectionLabel('photography'),items=groupProjects('photography');return `<section class="photography-page">${collectionHeader(title)}<div class="photography-series">${items.map(p=>{const slides=photoSlides(p);return `<article class="photography-series-item" id="${esc(p.id)}"><header><p class="eyebrow">${language==='zh'?'摄影系列':'Photography series'}</p><h2>${esc(tr(p.title))}</h2>${tr(p.date)?`<p class="series-date">${esc(tr(p.date))}</p>`:''}<p class="series-description ${tr(p.description)?'':'is-placeholder'}">${esc(tr(p.description)||(language==='zh'?'项目简介可在 Portfolio Manager 中添加。':'Add a project description in Portfolio Manager.'))}</p>${tr(p.role)?`<div class="role-block"><p class="role-label">${labels[language].role}</p><p class="role">${esc(tr(p.role))}</p></div>`:''}</header><div class="series-slideshow" data-photo-slider><div class="series-stage">${slides.map((slide,index)=>`<div class="photo-slide ${index===0?'is-active':''}" data-photo-slide aria-hidden="${index!==0}">${slide.map((src,i)=>`<figure><img src="${esc(src)}" alt="${esc(tr(p.title))} — ${labels[language].image} ${index+i+1}" loading="${index===0?'eager':'lazy'}" decoding="async"></figure>`).join('')}</div>`).join('')}</div><div class="series-toolbar"><span data-photo-count>01 / ${String(slides.length).padStart(2,'0')}</span>${slides.length>1?`<div><button type="button" data-photo-step="-1" aria-label="${labels[language].prevMedia}">${language==='zh'?'上一页':'Previous'}</button><button type="button" data-photo-step="1" aria-label="${labels[language].nextMedia}">${language==='zh'?'下一页':'Next'}</button></div>`:''}</div></div></article>`}).join('')}</div></section>`}
function stillsPage(){const photoTitle=sectionLabel('photography'),posterTitle=sectionLabel('poster'),posters=groupProjects('poster');return `<section class="index-page stills-overview"><header class="page-heading"><p class="eyebrow">${language==='zh'?'精选作品':'Selected work'}</p><h1>${activeGroup[language]}</h1></header><section class="stills-section"><header class="stills-section-heading"><h2><a href="${href('photography')}">${photoTitle}</a></h2><a href="${href('photography')}">${language==='zh'?'浏览全部':'View all'} </a></header><div class="project-grid">${photographyCards()}</div></section><section class="stills-section"><header class="stills-section-heading"><h2><a href="${href('poster')}">${posterTitle}</a></h2><a href="${href('poster')}">${language==='zh'?'浏览全部':'View all'} </a></header><div class="poster-grid poster-grid-preview">${posters.map(p=>`<figure><img src="${esc(cover(p))}" alt="${esc(tr(p.title))}" loading="lazy" decoding="async"></figure>`).join('')}</div></section></section>`}
function categoryOverview(g){return `<section class="index-page"><header class="page-heading"><p class="eyebrow">${language==='zh'?'精选作品':'Selected work'}</p><h1>${g[language]}</h1></header><div class="project-grid category-grid">${g.children.map(c=>{const items=groupProjects(c.id),roles=[...new Set(items.map(p=>tr(p.role)).filter(Boolean))];return `<a class="project-card" href="${href(c.id)}">${items.length?`<figure><img src="${esc(cover(items[0]))}" alt="${esc(c[language])}"></figure>`:''}<div class="card-meta"><h2>${c[language]}</h2></div><p class="card-caption">${esc(g.id==='interactive'?(language==='zh'?'开发者':'Developer'):roles.slice(0,2).join(' · '))}</p></a>`}).join('')}</div></section>`}
function categoryPage(){if(page==='poster')return posterPage();if(page==='photography')return photographyPage();const g=groups.find(g=>g.id===page);if(g)return categoryOverview(g);const title=g?.[language]||sectionLabel(page);const items=groupProjects(page);return `<section class="index-page"><header class="page-heading">${parentReturn()}<p class="eyebrow">${activeGroup&&page!==activeGroup.id?`${activeGroup[language]} / ${title}`:language==='zh'?'精选作品':'Selected work'}</p><h1>${title}</h1></header>${items.length?`<div class="project-grid">${items.map(p=>`<a class="project-card" href="${href('project-'+p.id)}"><figure><img src="${esc(cover(p))}" alt="${esc(tr(p.title))}" loading="lazy" decoding="async"></figure><div class="card-meta"><h2>${esc(tr(p.title))}</h2><span aria-hidden="true"></span></div><p class="card-caption">${esc(tr(p.date)||sectionLabel(p.section))}</p></a>`).join('')}</div>`:`<div class="empty-state"><h2>${labels[language].empty}</h2><p>${labels[language].emptyText}</p></div>`}</section>`}
function aboutPage(){return `<section class="about-page"><header class="page-heading"><p class="eyebrow">${labels[language].about}</p><h1>Xin(Robynn)Shen</h1></header><div class="about-body"><figure class="portrait"><img src="${PORTFOLIO.pages.portrait}" alt="${language==='zh'?'Xin (Robynn) Shen 的个人照片':'Portrait of Xin (Robynn) Shen'}"></figure><div class="about-copy"><p class="about-tagline">${esc(PORTFOLIO.pages.tagline)}</p><p class="bio">${esc(tr(PORTFOLIO.pages.bio))}</p><div class="contact-links">${PORTFOLIO.pages.links.map(l=>`<a href="${esc(l.url)}" ${l.url.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${l.label==='Gmail'?'xinshen.robynn@gmail.com':esc(l.label)}<span aria-hidden="true"></span></a>`).join('')}</div></div></div></section>`}
let mediaMode=project&&picturePages(project).length?'images':'films';
const mediaPosition={images:0,films:0};
function picturePages(p){if(Array.isArray(p.gallery)){const images=p.gallery.length?p.gallery:(p.cover?[p.cover]:[]);return Array.from({length:Math.ceil(images.length/2)},(_,i)=>images.slice(i*2,i*2+2))}return [...p.rows||[],...p.extraRows||[]]}
function filmPages(p){return [...(p.demo?[p.demo]:[]),...p.videos||[]]}
function mediaSources(v){return (v.webm?`<source src="${esc(v.webm)}" type="video/webm">`:'')+`<source src="${esc(v.src)}" type="video/mp4">`}
function projectLinks(p){if(Array.isArray(p.links))return p.links;return p.url?[{label:labels[language].visit,url:p.url}]:[]}
function projectPage(){const p=project,t=labels[language],siblings=activeGroup.id==='stills'?groupProjects(p.section):groupProjects(activeGroup.id),i=siblings.findIndex(x=>x.id===p.id),links=projectLinks(p);return `<article class="project-page" id="${p.id}"><header class="project-heading"><a class="breadcrumb" href="${href(p.section)}">${activeGroup[language]} / ${sectionLabel(p.section)}</a><span class="project-discipline">${esc(tr(p.discipline))}</span></header><div class="project-layout"><section class="project-info" aria-labelledby="project-title"><h1 id="project-title">${esc(tr(p.title))}</h1><p class="project-date">${esc(tr(p.date))}</p><p class="description">${esc(tr(p.description))}</p>${tr(p.role)?`<div class="role-block"><p class="role-label">${t.role}</p><p class="role">${esc(tr(p.role))}</p></div>`:''}<div class="media-tabs" role="tablist" aria-label="${language==='zh'?'项目媒体':'Project media'}">${picturePages(p).length?`<button role="tab" type="button" id="tab-images" aria-controls="media-panel" data-mode="images" aria-selected="${mediaMode==='images'}" tabindex="${mediaMode==='images'?0:-1}">${t.images}</button>`:''}${filmPages(p).length?`<button role="tab" type="button" id="tab-films" aria-controls="media-panel" data-mode="films" aria-selected="${mediaMode==='films'}" tabindex="${mediaMode==='films'?0:-1}">${t.films}</button>`:''}</div>${links.length?`<div class="project-links">${links.map(link=>`<a class="project-link" href="${esc(link.url)}" target="_blank" rel="noopener noreferrer">${esc(tr(link.label)||t.visit)}</a>`).join('')}</div>`:''}${p.metrics?`<p class="metrics">${esc(tr(p.metrics))}</p>`:''}</section><section class="media-panel" id="media-panel" role="tabpanel" aria-labelledby="tab-${mediaMode}" tabindex="0"></section></div><footer class="project-footer"><a href="${href(p.section)}"> ${t.back} ${sectionLabel(p.section)}</a><div>${i>0?`<a href="${href('project-'+siblings[i-1].id)}"> ${t.previous}</a>`:''}${i<siblings.length-1?`<a href="${href('project-'+siblings[i+1].id)}">${t.next} </a>`:''}</div></footer></article>`}
function stopMedia(){document.querySelectorAll('video').forEach(v=>{if(!v.paused)v.pause()})}
function renderMedia(){if(!project)return;stopMedia();const panel=document.querySelector('#media-panel'),items=mediaMode==='images'?picturePages(project):filmPages(project),pos=mediaPosition[mediaMode],item=items[pos],t=labels[language];panel.setAttribute('aria-labelledby','tab-'+mediaMode);let content='';if(mediaMode==='images'){const pictures=item.map(s=>typeof s==='object'?s.src:s);if(project.galleryLayout==='grid-4'&&pictures.length===4){content=`<div class="image-grid-four">${pictures.map((src,i)=>`<figure><img src="${esc(src)}" alt="${esc(tr(project.title))} — ${t.image} ${i+1}" decoding="async"></figure>`).join('')}</div>`}else{const ratios=pictures.map(s=>project.id==='ballerine'?2/3:(PORTFOLIO.dimensions[s]?.[0]||1)/(PORTFOLIO.dimensions[s]?.[1]||1));const total=ratios.reduce((a,b)=>a+b,0);content=`<div class="image-spread" style="--spread-ratio:${total};--spread-gaps:${Math.max(0,pictures.length-1)*8}px;grid-template-columns:${ratios.map(r=>r+'fr').join(' ')}">${pictures.map((src,i)=>`<figure><img src="${esc(src)}" alt="${esc(tr(project.title))} — ${t.image} ${picturePages(project).slice(0,pos).flat().length+i+1}" decoding="async"></figure>`).join('')}</div>`}}else{const dimensions=PORTFOLIO.dimensions[item.poster]||[16,9],ratio=dimensions[0]/dimensions[1];content=`<video controls playsinline preload="none" poster="${esc(item.poster)}" style="width:min(100cqw,calc(100cqh * ${ratio}))!important;height:auto!important;max-height:100cqh!important;aspect-ratio:${ratio}!important" aria-label="${esc(tr(item.title)||tr(project.title))}">${mediaSources(item)}</video>`}panel.innerHTML=`<div class="media-stage ${mediaMode==='films'?'film-stage':''}">${content}</div><div class="media-toolbar"><p class="media-caption" aria-live="polite">${mediaMode==='films'?esc(tr(item.title)||t.film):t.images} <span>${String(pos+1).padStart(2,'0')} / ${String(items.length).padStart(2,'0')}</span></p>${picturePages(project).length+filmPages(project).length>1?`<div class="media-arrows"><button type="button" data-step="-1" aria-label="${t.prevMedia}" ${pos===0&&(mediaMode==='images'||!picturePages(project).length)?'disabled':''}>${language==='zh'?'上一页':'Previous'}</button><button type="button" data-step="1" aria-label="${t.nextMedia}" ${pos===items.length-1&&(mediaMode==='films'||!filmPages(project).length)?'disabled':''}>${language==='zh'?'下一页':'Next'}</button></div>`:''}</div>`;document.querySelectorAll('[data-mode]').forEach(b=>{const active=b.dataset.mode===mediaMode;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1})}
function changeMedia(step){const images=picturePages(project),films=filmPages(project),items=mediaMode==='images'?images:films;const next=mediaPosition[mediaMode]+step;if(next<0){if(mediaMode!=='films'||!images.length)return;mediaMode='images';mediaPosition.images=images.length-1}else if(next>=items.length){if(mediaMode!=='images'||!films.length)return;mediaMode='films';mediaPosition.films=0}else mediaPosition[mediaMode]=next;renderMedia()}
function bindSwipe(el,step){let start=null;el.addEventListener('pointerdown',e=>{if(e.target.closest('button,a,video'))return;start={x:e.clientX,y:e.clientY,id:e.pointerId};el.setPointerCapture(e.pointerId)});el.addEventListener('pointercancel',()=>start=null);el.addEventListener('pointerup',e=>{if(!start||start.id!==e.pointerId)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.3)step(dx<0?1:-1)});el.addEventListener('dragstart',e=>e.preventDefault())}
function initPhotographySlides(){document.querySelectorAll('[data-photo-slider]').forEach(slider=>{const slides=[...slider.querySelectorAll('[data-photo-slide]')],count=slider.querySelector('[data-photo-count]');let current=0;const show=step=>{current=Math.max(0,Math.min(slides.length-1,current+step));slides.forEach((slide,i)=>{slide.classList.toggle('is-active',i===current);slide.setAttribute('aria-hidden',String(i!==current))});count.textContent=`${String(current+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}`;slider.querySelectorAll('[data-photo-step]').forEach(b=>b.disabled=Number(b.dataset.photoStep)<0?current===0:current===slides.length-1)};slider.querySelectorAll('[data-photo-step]').forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.photoStep))));bindSwipe(slider.querySelector('.series-stage'),show);show(0)})}

function render(){stopMedia();const t=labels[language];document.documentElement.lang=language;document.querySelector('#navigation').innerHTML=navigation();document.querySelector('#menu-toggle').textContent=t.menu;document.querySelector('.skip-link').textContent=t.skip;document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===language)));document.querySelector('#content').innerHTML=project?projectPage():page==='home'?home():page==='about'?aboutPage():categoryPage();const title=project?tr(project.title):page==='home'?t.selected:page==='about'?t.about:groups.find(g=>g.id===page)?.[language]||sectionLabel(page);document.title=title+' — Xin(Robynn)Shen';document.querySelector('meta[name=description]').content=project?tr(project.description):t.intro;if(project){renderMedia();bindSwipe(document.querySelector('#media-panel'),changeMedia)}if(page==='photography')initPhotographySlides()}
document.querySelector('#content').addEventListener('click',e=>{const mode=e.target.closest('[data-mode]'),step=e.target.closest('[data-step]');if(mode&&mode.dataset.mode!==mediaMode){mediaMode=mode.dataset.mode;renderMedia()}else if(step)changeMedia(Number(step.dataset.step))});
document.querySelector('#content').addEventListener('keydown',e=>{if(e.target.closest('[role=tablist]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-mode]')];let i=tabs.findIndex(b=>b===document.activeElement);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;mediaMode=tabs[i].dataset.mode;renderMedia();tabs[i].focus()}else if(e.target.id==='media-panel'&&mediaMode==='images'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();changeMedia(e.key==='ArrowRight'?1:-1)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.sidebar').classList.remove('is-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false')}});
document.addEventListener('play',e=>{if(e.target.tagName==='VIDEO')document.querySelectorAll('video').forEach(v=>{if(v!==e.target&&!v.paused)v.pause()})},true);
window.addEventListener('pagehide',stopMedia);


document.querySelectorAll('[data-language]').forEach(button=>button.addEventListener('click',()=>{language=button.dataset.language;try{localStorage.setItem('portfolio-language',language)}catch{}render()}));
document.querySelector('#menu-toggle').addEventListener('click',()=>{const open=document.querySelector('.sidebar').classList.toggle('is-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(open))});
render();
